import{_ as e,o as a,c as n,a2 as t}from"./chunks/framework.CZrxoOIU.js";const b=JSON.parse('{"title":"AI 辅助开发","description":"","frontmatter":{},"headers":[],"relativePath":"guide/advanced/ai-agent-skill.md","filePath":"guide/advanced/ai-agent-skill.md","lastUpdated":1793431572000}'),i={name:"guide/advanced/ai-agent-skill.md"};function l(p,s,r,o,d,c){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="ai-辅助开发" tabindex="-1">AI 辅助开发 <a class="header-anchor" href="#ai-辅助开发" aria-label="Permalink to &quot;AI 辅助开发&quot;">​</a></h1><p>WebApiClientCore 官方维护了一个 <strong>Agent Skill</strong>（<code>webapiclientcore</code>），让 Claude Code、Cursor 等支持 Agent Skills 约定的 AI 编程助手掌握 WebApiClientCore 的正确用法：让 AI 生成的接口声明、DI 注册、重试与 AOT 配置都符合官方最佳实践，而不是凭训练记忆&quot;猜&quot; API。</p><h2 id="skill-能做什么" tabindex="-1">Skill 能做什么 <a class="header-anchor" href="#skill-能做什么" aria-label="Permalink to &quot;Skill 能做什么&quot;">​</a></h2><p>安装后，当你在对话中提到声明式 HTTP 客户端、<code>WebApiClientCore</code>、<code>AddHttpApi</code>、<code>ITask</code> 重试、OAuth Token 管理等话题时，AI 会自动加载该技能，获得：</p><ul><li><strong>选型决策树</strong>：什么时候用 WebApiClientCore、什么时候直接用 HttpClient</li><li><strong>接口声明模板</strong>：HttpHost / HttpGet / JsonContent 等特性的正确组合</li><li><strong>常用代码模式</strong>：ITask 条件重试、异常返回默认值、文件上传、过滤器、OAuth2 Client Credentials、AOT 发布、JSON-RPC</li><li><strong>特性速查表</strong>：请求体格式（Json/Xml/Form/FormData/RawString）、响应解析、认证与请求头</li><li><strong>异常处理速查</strong>：<code>HttpRequestException</code> 包装下的具体异常类型与处理建议</li><li><strong>完整的参考手册</strong>（<code>reference.md</code>，约 1000 行）：覆盖自定义序列化、动态 HttpHost、数据验证、Cookie 刷新、畸形 API 适配等进阶场景</li></ul><h2 id="获取与安装" tabindex="-1">获取与安装 <a class="header-anchor" href="#获取与安装" aria-label="Permalink to &quot;获取与安装&quot;">​</a></h2><p>Skill 位于 <a href="https://github.com/dotnetcore/WebApiClient" target="_blank" rel="noreferrer">WebApiClient 仓库</a>的 <a href="https://github.com/dotnetcore/WebApiClient/tree/master/skills/webapiclientcore" target="_blank" rel="noreferrer"><code>skills/webapiclientcore</code></a> 目录，包含两个文件：</p><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><code>SKILL.md</code></td><td>Agent 执行指令：触发词、决策树、模板与模式</td></tr><tr><td><code>reference.md</code></td><td>完整参考手册</td></tr></tbody></table><p>将整个 <code>webapiclientcore</code> 目录复制到你使用的 AI 工具对应的项目技能目录即可：</p><table tabindex="0"><thead><tr><th>工具</th><th>技能目录</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>.claude/skills/webapiclientcore/</code></td></tr><tr><td>Cursor</td><td><code>.cursor/skills/webapiclientcore/</code></td></tr><tr><td>其他支持 Agent Skills 约定的工具</td><td>按其文档放置 <code>SKILL.md</code> 所在目录</td></tr></tbody></table><p>以 Claude Code 为例，在项目根目录执行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --depth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dotnetcore/WebApiClient.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmp-wac</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .claude/skills</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmp-wac/skills/webapiclientcore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .claude/skills/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmp-wac</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>也可以只下载两个文件，放入上述目录：</p><ul><li><a href="https://github.com/dotnetcore/WebApiClient/raw/master/skills/webapiclientcore/SKILL.md" target="_blank" rel="noreferrer">SKILL.md</a></li><li><a href="https://github.com/dotnetcore/WebApiClient/raw/master/skills/webapiclientcore/reference.md" target="_blank" rel="noreferrer">reference.md</a></li></ul><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h2><p>安装后无需额外操作，正常与 AI 对话即可。例如：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; 帮我调用 https://api.example.com 的用户接口，要支持失败重试</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（AI 自动加载 webapiclientcore skill，生成符合官方实践的代码）</span></span>
<span class="line"><span>[LoggingFilter]</span></span>
<span class="line"><span>[HttpHost(&quot;https://api.example.com/&quot;)]</span></span>
<span class="line"><span>public interface IUserApi</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    [HttpGet(&quot;api/users/{id}&quot;)]</span></span>
<span class="line"><span>    ITask&lt;User&gt; GetUserAsync(string id, CancellationToken token = default);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 使用：指数退避重试，仅网络异常时触发</span></span>
<span class="line"><span>var user = await api.GetUserAsync(id)</span></span>
<span class="line"><span>    .Retry(3, i =&gt; TimeSpan.FromSeconds(Math.Pow(2, i)))</span></span>
<span class="line"><span>    .WhenCatch&lt;HttpRequestException&gt;();</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h2 id="维护说明" tabindex="-1">维护说明 <a class="header-anchor" href="#维护说明" aria-label="Permalink to &quot;维护说明&quot;">​</a></h2><ul><li>Skill 随主仓库演进，API 变化（如 <code>v2.1.6</code> 的 ITokenProvider 取消令牌支持）会同步更新到 skill 与本文档。</li><li>如果发现 AI 生成的代码不符合最佳实践，欢迎在 <a href="https://github.com/dotnetcore/WebApiClient/issues" target="_blank" rel="noreferrer">WebApiClient 仓库</a>提 issue 反馈。</li></ul>`,19)])])}const k=e(i,[["render",l]]);export{b as __pageData,k as default};
